#!/usr/bin/env python3
"""Create an offline, searchable view of an existing finite-model result/certificate."""
from pathlib import Path
import argparse,json,hashlib,html
p=argparse.ArgumentParser(description=__doc__);p.add_argument('--result',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args()
result=json.loads(a.result.read_text());certfile=a.result.with_name('certificate.json');raw=certfile.read_bytes();certificate=json.loads(raw)
if hashlib.sha256(raw).hexdigest()!=result['certificate_sha256']:raise ValueError('Certificate digest mismatch')
if certificate['decision']!=result['decision']:raise ValueError('Decision mismatch')
if a.output.exists():p.error('Choose a new output file')
data=json.dumps({'result':result,'certificate':certificate},ensure_ascii=False).replace('&','\\u0026').replace('<','\\u003c').replace('>','\\u003e')
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>FG-DUCS · Result viewer</title>
<style>*{box-sizing:border-box}body{margin:0;background:#f5f7fa;color:#14283d;font:16px/1.55 system-ui,sans-serif}main{max-width:1140px;margin:auto;padding:32px}header{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #d8e1e9;padding-bottom:18px}.brand{font-weight:800;letter-spacing:.08em;color:#176d68}.sub{font-size:13px;color:#5b6f82}h1{overflow-wrap:anywhere;font-size:32px;line-height:1.2;margin:26px 0 12px}h2{font-size:20px}code{font-size:13px;overflow-wrap:anywhere}.pill{padding:6px 14px;border-radius:6px;font-weight:750;background:#dcf3e8;color:#116544}.loss{background:#fde9db;color:#97451a}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin:24px 0}.card,section{background:white;border:1px solid #dce5ec;border-radius:10px;padding:20px}.card b{display:block;font-size:27px}.card span{font-size:13px;color:#596d80}.checks{display:flex;gap:24px;flex-wrap:wrap;padding:12px 0}.checks span{color:#176d68;font-weight:600}section{margin-top:18px}table{width:100%;border-collapse:collapse;font-size:13px}th,td{text-align:left;padding:9px 12px;border-bottom:1px solid #e4eaf0;vertical-align:top}th{background:#f0f5f9}input{width:100%;padding:11px;border:1px solid #bdcbd7;border-radius:6px;margin-bottom:16px;font-size:14px}.muted{color:#64798c}.tablewrap{max-height:410px;overflow:auto}.checks small{font-weight:400}.foot{margin:24px 0;font-size:13px;color:#596d80}details{margin-top:16px}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}@media(max-width:750px){.cards{grid-template-columns:repeat(2,1fr)}main{padding:16px}}</style>
<main><header><div><div class="brand">FG-DUCS</div><div class="sub">Finite dynamic update · Local result viewer</div></div><span id="badge" class="pill"></span></header>
<h1 id="name"></h1><div class="muted" id="config"></div><div class="cards" id="cards"></div>
<section><h2>Recorded verification</h2><div class="checks" id="checks"></div><p class="sub">The viewer checks the certificate file digest and matching decisions. The PASS fields below were recorded by the solver's native checkers; viewing them does not rerun semantic verification.</p></section>
<section><h2 id="policyTitle">Policy and completion</h2><p id="interpretation"></p><div class="tablewrap"><table><thead id="edgehead"></thead><tbody id="edges"></tbody></table></div></section>
<section><h2>Certificate states</h2><input id="search" placeholder="Filter by state, component, pending event or requirement…"><div class="tablewrap"><table><thead><tr><th>ID</th><th>Physical states</th><th>Requirements</th><th>Pending</th><th>Rank / flags</th></tr></thead><tbody id="states"></tbody></table></div><p id="stateCount" class="sub"></p></section>
<details><summary>Result metadata and evidence identifiers</summary><pre id="metadata"></pre></details><p class="foot">A WIN guarantees safe finite completion only relative to the supplied finite game and its assumptions. Adapter conformance, real deployment, and service continuity beyond the modeled requirements are separate obligations. Local replication timings are not paper measurements.</p></main>
<script id="data" type="application/json">DATA_HERE</script><script>
const {result:r,certificate:c}=JSON.parse(document.getElementById('data').textContent);const $=id=>document.getElementById(id);const txt=(id,t)=>$(id).textContent=t;const esc=x=>String(x??'—').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
txt('badge',r.decision);if(r.decision==='LOSS')$('badge').classList.add('loss');txt('name',r.id);txt('config',`Family: ${r.family} · Solver: ${r.solver} · Merge: ${r.merge} · Java: ${r.java_version}`);
$('cards').innerHTML=[['Discovered states',r.states_discovered],['Successor queries',r.successor_queries],['Certificate states',c.states.length],['Worst completion rank',r.worst_completion_rank]].map(([t,v])=>`<div class="card"><span>${esc(t)}</span><b>${esc(v)}</b></div>`).join('');
$('checks').innerHTML=[['Endpoints',r.endpoint_checker],['Certificate',r.certificate_checker],['Link',r.link_checker||'not applicable']].map(([t,v])=>`<span>${esc(t)}: ${esc(v)}</span>`).join('');
if(r.decision==='WIN'){txt('interpretation','Each policy action below retains all its adversarial outcomes. A decreasing completion rank certifies arrival at an admitted handover state.');$('edgehead').innerHTML='<tr><th>From state</th><th>Action</th><th>To state</th></tr>';$('edges').innerHTML=(c.strategy_edges||[]).map(e=>'<tr>'+e.map(x=>'<td>'+esc(x)+'</td>').join('')+'</tr>').join('');}else{txt('policyTitle','Losing-region evidence');txt('interpretation','At least one admitted entry cannot ensure safe finite completion. These sampled entry-action buckets show why a policy cannot leave the stored losing region safely; ordinary loops do not establish completion.');$('edgehead').innerHTML='<tr><th>Entry action</th><th>Kind</th><th>Outcomes</th><th>Unsafe outcomes</th><th>In losing region</th></tr>';$('edges').innerHTML=(r.loss_summary?.initial_examples||[]).flatMap(x=>x.enabled_action_buckets||[]).map(x=>'<tr>'+[x.action,x.update?'update':'ordinary',x.outcomes,x.unsafe_outcomes,x.outcomes_in_certificate_region].map(v=>'<td>'+esc(v)+'</td>').join('')+'</tr>').join('');}
function draw(){const q=$('search').value.toLowerCase();const s=c.states.filter(x=>JSON.stringify(x).toLowerCase().includes(q));$('states').innerHTML=s.map(x=>`<tr><td>${x.id}</td><td>${esc(x.physical.map(([v,p])=>v+': '+p).join(' / '))}</td><td>${esc(JSON.stringify(x.testers))}</td><td>${esc(x.pending.join(', ')||'none')}</td><td>${esc(x.rank??'—')}${x.initial?' · initial':''}${x.goal?' · goal':''}${x.safe?'':' · unsafe'}</td></tr>`).join('');txt('stateCount',`${s.length} of ${c.states.length} certificate states shown`);} $('search').oninput=draw;draw();txt('metadata',JSON.stringify(r,null,2));
</script></html>'''
a.output.parent.mkdir(parents=True,exist_ok=True);a.output.write_text(page.replace('DATA_HERE',data));print('Viewer:',a.output)
